return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'fi','project-id-version'=>'Babilim 1.2.0','pot-creation-date'=>'2026-11-05T19:50:50+00:00','po-revision-date'=>'2026-11-05T19:50:50+00:00','x-generator'=>'Babilim','messages'=>['Babilim'=>'Babilim','Fills in missing translations for the plugins and themes already installed on your site.'=>'Täydentää sivustollesi asennettujen lisäosien ja teemojen puuttuvat käännökset.','That upload screen was out of date: a different upload has been prepared since. Nothing was sent. Review the current one from the Translations list.'=>'Tämä siirtonäkymä oli vanhentunut: sen jälkeen on valmisteltu eri siirto. Mitään ei lähetetty. Tarkista nykyinen siirto Käännösluettelosta.','The free service plan gives each site a limited number of slots for plugins and themes; the slots in use are shown in Settings after you enable Babilim.'=>'Ilmainen palvelupaketti antaa jokaiselle sivustolle rajoitetun määrän paikkoja lisäosille ja teemoille. Käytössä olevat paikat näkyvät Asetuksissa, kun Babilim on otettu käyttöön.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site (the limit is %1$d for themes and %2$d for plugins), unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Käännöksen pyytäminen sijoittaa tämän lisäosan tai teeman yhteen tämän sivuston ilmaisen palvelupaketin paikoista (raja on %1$d teemoille ja %2$d lisäosille), ellei sillä jo ole paikkaa. Paikka pysyy käytössä, eikä epäonnistunut käännös vapauta sitä.','Requesting a translation puts this plugin or theme on one of the free service plan\'s slots for this site, unless it already has one. A slot stays used, and a failed translation does not free it.'=>'Käännöksen pyytäminen sijoittaa tämän lisäosan tai teeman yhteen tämän sivuston ilmaisen palvelupaketin paikoista, ellei sillä jo ole paikkaa. Paikka pysyy käytössä, eikä epäonnistunut käännös vapauta sitä.','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one (the limit is %1$d for themes and %2$d for plugins). A slot stays used, and a failed translation does not free it. Continue?'=>'Jos tämä lisäosa tai teema ei vielä ole yhdellä tämän sivuston ilmaisen palvelupaketin paikoista, käännöksen pyytäminen sijoittaa sen yhteen (raja on %1$d teemoille ja %2$d lisäosille). Paikka pysyy käytössä, eikä epäonnistunut käännös vapauta sitä. Jatketaanko?','If this plugin or theme is not on one of the free service plan\'s slots for this site yet, requesting a translation puts it on one. A slot stays used, and a failed translation does not free it. Continue?'=>'Jos tämä lisäosa tai teema ei vielä ole yhdellä tämän sivuston ilmaisen palvelupaketin paikoista, käännöksen pyytäminen sijoittaa sen yhteen. Paikka pysyy käytössä, eikä epäonnistunut käännös vapauta sitä. Jatketaanko?','%1$d site on this network is set to erase its Babilim identity when the plugin is deleted. The paid license attached to that site could then not be restored automatically; you would have to contact Babilim support at %2$s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in that site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'%1$d tämän verkoston sivusto on asetettu tyhjentämään Babilim-tunnisteensa, kun lisäosa poistetaan. Kyseiseen sivustoon liitettyä maksullista lisenssiä ei sen jälkeen voisi palauttaa automaattisesti, vaan sinun pitäisi ottaa yhteyttä Babilim-tukeen osoitteessa %2$s. Säilyttääksesi tunnisteen paina Peruuta, poista valinta kohdasta "Poista kaikki Babilim-tiedot poistettaessa" kyseisen sivuston Babilim-asetuksista ja poista käytöstä uudelleen. Poistetaanko käytöstä silti?' . "\0" . '%1$d tämän verkoston sivustoa on asetettu tyhjentämään Babilim-tunnisteensa, kun lisäosa poistetaan. Näihin sivustoihin liitettyjä maksullisia lisenssejä ei sen jälkeen voisi palauttaa automaattisesti, vaan sinun pitäisi ottaa yhteyttä Babilim-tukeen osoitteessa %2$s. Säilyttääksesi tunnisteet paina Peruuta, poista valinta kohdasta "Poista kaikki Babilim-tiedot poistettaessa" kunkin sivuston Babilim-asetuksista ja poista käytöstä uudelleen. Poistetaanko käytöstä silti?','%1$s %2$s.'=>'%1$s %2$s.','%1$s (%2$s): %3$s'=>'%1$s (%2$s): %3$s','%1$s nothing to do.'=>'%1$s ei tehtävää.','%1$s: %2$s'=>'%1$s: %2$s','%1$s: %2$s (%3$s)'=>'%1$s: %2$s (%3$s)','%1$s: %2$s. Choose the language.'=>'%1$s: %2$s. Valitse kieli.','%d failed'=>'%d epäonnistui' . "\0" . '%d epäonnistui','%d not yet tried'=>'%d ei vielä yritetty' . "\0" . '%d ei vielä yritetty','%d report is waiting. "Always share" and "Don\'t share" apply to all of them.'=>'%d raportti odottaa. "Jaa aina" ja "Älä jaa" koskevat kaikkia niitä.' . "\0" . '%d raporttia odottaa. "Jaa aina" ja "Älä jaa" koskevat kaikkia niitä.','%d skipped'=>'%d ohitettiin' . "\0" . '%d ohitettiin','%d succeeded'=>'%d onnistui' . "\0" . '%d onnistui','%d to install'=>'%d asennettavaksi' . "\0" . '%d asennettavaksi','(a public key generated for this site)'=>'(tälle sivustolle luotu julkinen avain)','(detected)'=>'(tunnistettu)','(generic codes and coordinates only)'=>'(vain yleiset koodit ja koordinaatit)','A cleanup was paused on %1$s: %2$s. Nothing was deleted.'=>'Siivous keskeytettiin ajankohtana %1$s: %2$s. Mitään ei poistettu.','A file in the component could not be read, so it was not packaged.'=>'Osan tiedostoa ei voitu lukea, joten sitä ei pakattu.','A host that serves only one PHP request at a time cannot complete this step.'=>'Palvelin, joka käsittelee vain yhden PHP-pyynnön kerrallaan, ei voi suorittaa tätä vaihetta loppuun.','A part of the upload kept failing, so the upload was cancelled.'=>'Siirron yksi osa epäonnistui toistuvasti, joten siirto peruttiin.','A translation cannot be requested for that locale on this site right now.'=>'Tälle kielialueelle ei voi tällä hetkellä pyytää käännöstä tällä sivustolla.','A translation-index write conflicted with another request on %1$s (%2$s) and was not applied; the most recent version was kept.'=>'Käännösindeksin kirjoitus ajankohtana %1$s (%2$s) oli ristiriidassa toisen pyynnön kanssa eikä sitä otettu käyttöön; uusin versio säilytettiin.','A translation-index write on %1$s (%2$s) could not be completed and was not applied (%3$s).'=>'Käännösindeksin kirjoitusta ajankohtana %1$s (%2$s) ei voitu suorittaa loppuun eikä sitä otettu käyttöön (%3$s).','Account'=>'Tili','Add another language'=>'Lisää toinen kieli','Advanced'=>'Lisäasetukset','All'=>'Kaikki','All free-plan slots for this site are used'=>'Kaikki tämän sivuston ilmaispaketin paikat ovat käytössä','All languages'=>'Kaikki kielet','Already in WordPress core'=>'Jo WordPressin ytimessä','Already installed.'=>'Asennettu jo.','Always share'=>'Jaa aina','Another installation is running; try again in a moment.'=>'Toinen asennus on käynnissä; yritä hetken kuluttua uudelleen.','Automatic installs'=>'Automaattiset asennukset','Automatic installs are now off; turn them on again in the settings if you want them.'=>'Automaattiset asennukset on nyt poistettu käytöstä; voit ottaa ne uudelleen käyttöön asetuksissa, jos haluat.','Available'=>'Saatavilla','Available translations can be installed with one click, and missing ones can be requested. While automatic installs are on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Saatavilla olevat käännökset voi asentaa yhdellä napsautuksella, ja puuttuvia voi pyytää. Kun automaattiset asennukset ovat käytössä, käännökset, jotka palvelu ilmoittaa saatavilla oleviksi hallinnoimillesi kielille, asennetaan kahdesti päivässä tapahtuvan synkronoinnin aikana.','Available · %s'=>'Saatavilla · %s','Babilim Settings'=>'Babilim Asetukset','Babilim adds translations for every language checked here.'=>'Babilim lisää käännökset jokaiselle tässä valitulle kielelle.','Babilim could not confirm a temporary folder outside the website, so the component was not packaged and nothing was uploaded. Define BABILIM_TEMP_DIR in wp-config.php as a writable folder outside the web root (for example a folder next to, not inside, your site\'s public directory), or ask your host for one.'=>'Babilim ei voinut vahvistaa verkkosivuston ulkopuolella olevaa väliaikaista kansiota, joten komponenttia ei paketoitu eikä mitään ladattu palveluun. Määritä BABILIM_TEMP_DIR tiedostossa wp-config.php kirjoitettavaksi kansioksi verkkojuurikansion ulkopuolella (esimerkiksi kansio sivustosi julkisen hakemiston vieressä, ei sen sisällä) tai pyydä sellainen palveluntarjoajaltasi.','Babilim could not finish checking this site.'=>'Babilim ei voinut suorittaa tämän sivuston tarkistusta loppuun.','Babilim could not finish enabling (%1$s): %2$s'=>'Babilimin käyttöönotto ei onnistunut (%1$s): %2$s','Babilim could not finish verifying this site (the service could not reach it back). Registration is paused.'=>'Babilim ei voinut viimeistellä tämän sivuston vahvistamista (palvelu ei saanut yhteyttä takaisin sivustoon). Rekisteröinti on keskeytetty.','Babilim could not verify this site, so nothing is downloaded or installed until verification succeeds.'=>'Babilim ei voinut vahvistaa tätä sivustoa, joten mitään ei ladata tai asenneta ennen kuin vahvistus onnistuu.','Babilim could not verify this site, so nothing is downloaded or installed.'=>'Babilim ei pystynyt vahvistamaan tätä sivustoa, joten mitään ei ladata tai asenneta.','Babilim finds the plugins and themes on this site that have no translation for your language and installs one for each.'=>'Babilim etsii tämän sivuston lisäosat ja teemat, joilla ei ole käännöstä kielellesi, ja asentaa niille kullekin käännöksen.','Babilim has not been enabled for this site yet.'=>'Babilimia ei ole vielä otettu käyttöön tällä sivustolla.','Babilim has not installed any translation for this language.'=>'Babilim ei ole asentanut yhtään käännöstä tälle kielelle.','Babilim hit an error. Share an error report?'=>'Babilim kohtasi virheen. Jaetaanko virheraportti?','Babilim installed %d translation automatically since your last visit.'=>'Babilim asensi automaattisesti %d käännöksen edellisen käyntisi jälkeen.' . "\0" . 'Babilim asensi automaattisesti %d käännöstä edellisen käyntisi jälkeen.','Babilim is disabled. Nothing more is sent; translations already installed keep working.'=>'Babilim on poissa käytöstä. Mitään ei lähetetä enää; jo asennetut käännökset toimivat edelleen.','Babilim is enabled: this site is verified and %d component was found.'=>'Babilim on käytössä: tämä sivusto on vahvistettu ja %d komponentti löytyi.' . "\0" . 'Babilim on käytössä: tämä sivusto on vahvistettu ja %d komponenttia löytyi.','Babilim is enabling and checking this site… (last attempt: %s)'=>'Babilimin käyttöönotto ja tämän sivuston tarkistus ovat käynnissä… (viimeisin yritys: %s)','Babilim is enabling and checking this site… Reload this page or wait for the scheduled check to finish.'=>'Babilimin käyttöönotto ja tämän sivuston tarkistus ovat käynnissä… Lataa tämä sivu uudelleen tai odota ajastetun tarkistuksen valmistumista.','Babilim is not enabled.'=>'Babilim ei ole käytössä.','Babilim is set to erase this site\'s identity when the plugin is deleted. The paid license attached to this site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identity, press Cancel, untick "Delete all Babilim data on uninstall" in the Babilim settings, and deactivate again. Deactivate anyway?'=>'Babilim on asetettu tyhjentämään tämän sivuston tunniste, kun lisäosa poistetaan. Sivustoon liitettyä maksullista lisenssiä ei sen jälkeen voisi palauttaa automaattisesti, vaan sinun pitäisi ottaa yhteyttä Babilim-tukeen osoitteessa %s. Säilyttääksesi tunnisteen paina Peruuta, poista valinta kohdasta "Poista kaikki Babilim-tiedot poistettaessa" Babilim-asetuksista ja poista käytöstä uudelleen. Poistetaanko käytöstä silti?','Babilim ran out of time for this step and will continue on the next check.'=>'Babilimin aika loppui tämän vaiheen osalta, ja se jatkaa seuraavalla tarkistuksella.','Babilim settings'=>'Babilim Asetukset','Babilim sync is temporarily delayed by the service (rate limited); it will try again after %s.'=>'Palvelu on viivästyttänyt Babilim-synkronointia tilapäisesti (nopeusrajoitus); se yrittää uudelleen ajankohdan %s jälkeen.','Babilim was updated while this upload was waiting. The old package was discarded; please confirm the upload again.'=>'Babilim päivitettiin tämän siirron odottaessa. Vanha paketti hylättiin; vahvista siirto uudelleen.','Babilim will upload these files from %1$s (version %2$s): every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in its main folder. They are used to find the text that needs translating and to identify the plugin or theme.'=>'Babilim siirtää nämä tiedostot kohteesta %1$s (versio %2$s): jokaisen .php- ja .js-tiedoston, jokaisen block.json-tiedoston sekä pääkansion tiedostot readme.txt, readme.md, style.css ja theme.json. Niiden avulla etsitään käännettävä teksti ja tunnistetaan lisäosa tai teema.','Babilim_Manifest is unavailable: %s'=>'Babilim_Manifest ei ole käytettävissä: %s','Back'=>'Takaisin','Bought a license for this domain before? Enter the restore code you received at checkout.'=>'Oletko ostanut lisenssin tälle verkkotunnukselle aiemmin? Anna kassalla saamasi palautuskoodi.','Broken placeholder'=>'Rikkinäinen paikkamerkki','Build'=>'Koontiversio','Built'=>'Koostettu','Bulk actions apply only to the selected language of each selected component.'=>'Massatoiminnot koskevat vain jokaisen valitun komponentin valittua kieltä.','Bulk actions apply to every matching language of each selected component.'=>'Massatoiminnot koskevat jokaisen valitun komponentin kaikkia vastaavia kieliä.','Bulk download:'=>'Massalataus:','Bulk request:'=>'Massapyyntö:','Bulk update:'=>'Massapäivitys:','Bundled with the plugin'=>'Sisältyy lisäosaan','Bundled with the theme'=>'Sisältyy teemaan','By clicking Enable, you agree to send the information listed above to Babilim.'=>'Valitsemalla Ota käyttöön hyväksyt yllä luetelluiden tietojen lähettämisen Babilimille.','By continuing you confirm that you have the right to upload this component.'=>'Jatkamalla vahvistat, että sinulla on oikeus siirtää tämä komponentti.','Cancel'=>'Peruuta','Category'=>'Kategoria','Check again'=>'Tarkista uudelleen','Check again now'=>'Tarkista uudelleen nyt','Checkout is not available for this site right now.'=>'Kassa ei ole tällä hetkellä käytettävissä tälle sivustolle.','Choose'=>'Valitse','Choose a category…'=>'Valitse kategoria…','Choose a language'=>'Valitse kieli','Choose a language…'=>'Valitse kieli…','Clear filters'=>'Tyhjennä suodattimet','Close'=>'Sulje','Component'=>'Komponentti','Confirm'=>'Vahvista','Conflicting keys'=>'Ristiriitaiset avaimet','Continue'=>'Jatka','Continue next batch (%d left)'=>'Jatka seuraavaan erään (%d jäljellä)','Continuing…'=>'Jatketaan…','Could not back up %s before replacing it.'=>'Tiedostosta %s ei voitu tehdä varmuuskopiota ennen sen korvaamista.','Could not create the package archive.'=>'Pakettiarkistoa ei voitu luoda.','Could not determine active components; the existing merged index was left unchanged.'=>'Aktiivisia komponentteja ei voitu selvittää; olemassa olevaa yhdistettyä indeksiä ei muutettu.','Could not determine installed plugins/themes; sweep skipped, nothing was deleted.'=>'Asennettuja lisäosia/teemoja ei voitu selvittää; tarkistus ohitettiin, mitään ei poistettu.','Could not load the full WordPress.org locale list from the service, so no other language can be added right now.'=>'WordPress.org-kielikoodien täydellistä luetteloa ei voitu ladata palvelusta, joten muita kieliä ei voi lisätä juuri nyt.','Could not move %s into place.'=>'Tiedostoa %s ei voitu siirtää paikalleen.','Could not move the merged index for \'%s\' into place; the previous served index (if any) was removed rather than left half-updated. No default-domain supplement is served for this locale until the next successful rebuild.'=>'Kielen \'%s\' yhdistettyä indeksiä ei voitu siirtää paikalleen; aiempi tarjottu indeksi (jos sellainen oli) poistettiin sen sijaan, että se olisi jätetty puoliksi päivitetyksi. Tälle kielelle ei tarjota oletustekstialueen täydennystä ennen seuraavaa onnistunutta uudelleenrakennusta.','Could not open zip: %s'=>'Zip-tiedostoa ei voitu avata: %s','Could not prepare %s for rollback.'=>'Tiedostoa %s ei voitu valmistella aiempaan versioon palauttamista varten.','Could not read %s back after moving it into place.'=>'Tiedostoa %s ei voitu lukea takaisin sen siirtämisen jälkeen paikalleen.','Could not read: %s'=>'Lukeminen epäonnistui: %s','Could not restore the purchase: %s'=>'Ostosta ei voitu palauttaa: %s','Could not show a new restore code: %s'=>'Uuden palautuskoodin näyttäminen epäonnistui: %s','Could not stage %s'=>'Tiedostoa %s ei voitu valmistella käyttöönottoa varten','Could not stage default/%s'=>'Tiedostoa default/%s ei voitu valmistella käyttöönottoa varten','Could not start checkout: %s'=>'Kassan aloittaminen epäonnistui: %s','Could not verify entry count for %s'=>'Merkintöjen määrää ei voitu varmistaa: %s','Could not write the downloaded package to disk.'=>'Ladatun paketin kirjoittaminen levylle epäonnistui.','Could not write the staged merged index.'=>'Vaiheistetun yhdistetyn indeksin kirjoittaminen epäonnistui.','Current translation'=>'Nykyinen käännös','Custom overrides'=>'Omat ohitukset','Danger zone'=>'Vaaravyöhyke','Default supplement entry count mismatch.'=>'Default-lisäosan merkintöjen määrä ei täsmää.','Delete all Babilim data on uninstall'=>'Poista kaikki Babilim-tiedot poistettaessa','Disable Babilim'=>'Poista Babilim käytöstä','Disable Babilim? Installed translations are kept, but no further checks or downloads will run.'=>'Poistetaanko Babilim käytöstä? Asennetut käännökset säilytetään, mutta tarkistuksia tai latauksia ei enää suoriteta.','Don\'t share'=>'Älä jaa','Download'=>'Lataa','Downloaded and installed.'=>'Ladattu ja asennettu.','Downloading…'=>'Ladataan…','Downloads: %1$d/%2$d (%3$s)'=>'Lataukset: %1$d/%2$d (%3$s)','Each component\'s own contribution to each locale\'s shared default-domain supplement.'=>'Kunkin komponentin oma osuus kunkin kielen jaettuun oletustekstialueen täydennykseen.','Enable Babilim'=>'Ota Babilim käyttöön','Enabling…'=>'Otetaan käyttöön…','English (United States)'=>'englanti (Yhdysvallat)','Entries'=>'Merkinnät','Entry count mismatch for %s'=>'Merkintöjen määrä ei täsmää: %s','Error reports'=>'Virheraportit','Every installed plugin/theme: its slug, version, text domain(s), whether it\'s a wp.org listing, its own bundled locales, and which locales you\'ve already installed a Babilim translation for.'=>'Jokainen asennettu lisäosa/teema: sen slug, versio, tekstialueet, onko se WordPress.org-listaus, sen omat mukana tulevat kielialueet ja mihin kielialueisiin olet jo asentanut Babilim-käännöksen.','Every locale in use on this site (site locale, installed language packs, user locales, and any you add manually). No locale is treated differently from another.'=>'Kaikki tällä sivustolla käytössä olevat kielialueet (sivuston kielialue, asennetut kielipaketit, Käyttäjä-kohtaiset kielialueet ja itse lisäämäsi). Mitään kielialuetta ei kohdella toisin kuin muita.','Excluded'=>'Poissuljettu','Files with other names or extensions are not included, nor are the uploads, cache, logs, backup, data, vendor, node_modules and languages folders, hidden files, or files whose names match common secrets (wp-config*, .env*, *.sql, *.log, *.pem, *.key). Code files can still contain text or data you would not want to share; check them if you are unsure. The service removes the same kinds of files again on arrival.'=>'Tiedostoja, joilla on muu nimi tai tiedostopääte, ei oteta mukaan. Myöskään kansioita uploads, cache, logs, backup, data, vendor, node_modules ja languages, piilotiedostoja tai tiedostoja, joiden nimet vastaavat tavallisia luottamuksellisten tiedostojen nimimalleja (wp-config*, .env*, *.sql, *.log, *.pem, *.key), ei oteta mukaan. Kooditiedostot voivat silti sisältää tekstiä tai dataa, jota et halua jakaa; tarkista ne, jos olet epävarma. Palvelu poistaa samantyyppiset tiedostot vielä uudelleen vastaanoton yhteydessä.','Free'=>'Ilmainen','Free-plan slots'=>'Ilmaispaketin paikat','General'=>'Yleiset','If this is on, uninstalling also erases this site\'s identity. The paid license attached to this site cannot be restored automatically afterwards; you would have to contact Babilim support at %s to get it back.'=>'Jos tämä on päällä, poistaminen tyhjentää myös tämän sivuston tunnisteen. Sivustoon liitettyä maksullista lisenssiä ei voi sen jälkeen palauttaa automaattisesti, vaan sinun on otettava yhteyttä Babilim-tukeen osoitteessa %s sen palauttamiseksi.','Included'=>'Sisällytetty','Included in index'=>'Mukana indeksissä','Install available translations automatically'=>'Asenna saatavilla olevat käännökset automaattisesti','Installed'=>'Asennettu','Installed translations are kept, but no further checks or downloads will run.'=>'Asennetut käännökset säilytetään, mutta tarkistuksia tai latauksia ei enää suoriteta.','Installed · %s'=>'Asennettu · %s','Installed · built for %1$s, this site has %2$s'=>'Asennettu · tehty versiolle %1$s, tällä sivustolla on %2$s','Installed · built for %s'=>'Asennettu · tehty versiolle %s','Installed · built for %s, all free-plan slots for this site are used'=>'Asennettu · tehty versiolle %s, kaikki tämän sivuston ilmaispaketin paikat ovat käytössä','Installed · built for %s, new version failed'=>'Asennettu · tehty versiolle %s, uusi versio epäonnistui','Installed · built for %s, new version not covered by the free service plan'=>'Asennettu · tehty versiolle %s, uutta versiota ei kata ilmainen palvelupaketti','Installed · built for %s, new version scheduled'=>'Asennettu · tehty versiolle %s, uusi versio ajoitettu','Installed · built for %s, translating the new version…'=>'Asennettu · tehty versiolle %s, uutta versiota käännetään…','Installed · built for a different version'=>'Asennettu · tehty eri versiolle','Installed · built for a different version, all free-plan slots for this site are used'=>'Asennettu · tehty eri versiolle, kaikki tämän sivuston ilmaispaketin paikat ovat käytössä','Installed · built for a different version, new version failed'=>'Asennettu · tehty eri versiolle, uusi versio epäonnistui','Installed · built for a different version, new version not covered by the free service plan'=>'Asennettu · tehty eri versiolle, uutta versiota ei kata ilmainen palvelupaketti','Installed · built for a different version, new version scheduled'=>'Asennettu · tehty eri versiolle, uusi versio ajoitettu','Installed · built for a different version, translating the new version…'=>'Asennettu · tehty eri versiolle, uutta versiota käännetään…','It is stored by the service\'s hosting provider and processed by AI models to produce the translation.'=>'Sen tallennuksesta vastaa palvelun palveluntarjoaja, ja tekoälymallit käsittelevät sen käännöksen tuottamiseksi.','Keep my own translation overrides when purging everything or uninstalling this plugin.'=>'Säilytä omat käännösten ohitukseni, kun kaikki tyhjennetään tai tämä lisäosa poistetaan.','Language'=>'Kieli','Language:'=>'Kieli:','Languages'=>'Kielet','Languages found on this site: %s.'=>'Tältä sivustolta löytyneet kielet: %s.','Last cleanup on %1$s: %2$d newly marked, %3$d file(s) deleted, %4$d record(s) removed.'=>'Viimeisin siivous %1$s: %2$d uutta merkittyä, %3$d tiedostoa poistettu, %4$d tietuetta poistettu.','Maintenance'=>'Ylläpito','Maintenance status is not available right now.'=>'Ylläpidon tila ei ole tällä hetkellä saatavilla.','Manifest unavailable: %s'=>'Manifesti ei ole saatavilla: %s','Negation reversed'=>'Kielto käännetty päinvastaiseksi','No'=>'Ei','No build is available to download for this locale.'=>'Tälle kielelle ei ole ladattavaa versiota.','No cleanup has run yet.'=>'Siivousta ei ole vielä suoritettu.','No components match these filters. %s'=>'Mikään komponentti ei vastaa näitä suodattimia. %s','No components synced yet.'=>'Komponentteja ei ole vielä synkronoitu.','No installed translation matches.'=>'Mikään asennettu käännös ei vastaa hakua.','No language is managed yet.'=>'Yhtään kieltä ei ole vielä hallinnassa.','No pending challenge for this nonce.'=>'Tälle noncelle ei ole odottavaa haastetta.','No pending challenge to verify.'=>'Ei vahvistettavaa odottavaa haastetta.','No plugins or themes found.'=>'Lisäosia tai teemoja ei löytynyt.','No previous build to roll back to.'=>'Aiempaa koontiversiota, johon palata, ei ole.','No record for %s'=>'Ei tietuetta kohteelle %s','No site id is on file to rotate a token for.'=>'Sivuston tunnusta, jolle tunniste voitaisiin vaihtaa, ei ole tallennettu tiedostoon.','No — component inactive'=>'Ei — komponentti ei ole käytössä','No — component removed'=>'Ei — komponentti on poistettu','No — installed version differs from the active one'=>'Ei – asennettu versio poikkeaa aktiivisesta','Not a valid server_build_id: %s'=>'Virheellinen server_build_id: %s','Not covered by the free service plan'=>'Ilmainen palvelupaketti ei kata tätä','Not installed'=>'Ei asennettu','Not registered yet'=>'Ei vielä rekisteröity','Not supported'=>'Ei tuettu','Not verified'=>'Ei vahvistettu','Note (optional)'=>'Huomautus (valinnainen)','Nothing to choose.'=>'Ei valittavaa.','Nothing to confirm.'=>'Ei vahvistettavaa.','Off by default: deleting the plugin keeps this site\'s identity, so a reinstall can reuse it.'=>'Oletuksena pois päältä: lisäosan poistaminen säilyttää tämän sivuston tunnisteen, jotta uudelleenasennus voi käyttää sitä.','One or more served files no longer match the manifest.'=>'Yksi tai useampi tarjottu tiedosto ei enää vastaa manifestia.','One-time purchase for this site: %1$s %2$s. Includes all future translation updates. Payment is handled by Paddle in a new tab.'=>'Kertaostos tälle sivustolle: %1$s %2$s. Sisältää kaikki tulevat käännöspäivitykset. Maksun käsittelee Paddle uudessa välilehdessä.','Only a network administrator can do this, because it changes translation files shared by every site on this network.'=>'Vain verkon ylläpitäjä voi tehdä tämän, koska se muuttaa käännöstiedostoja, jotka ovat kaikkien tämän verkon sivustojen yhteiskäytössä.','Only plugins and themes can be packaged.'=>'Vain lisäosia ja teemoja voi pakata.','Only when you confirm an upload for a plugin or theme that is not on WordPress.org: every .php and .js file, every block.json file, and the readme.txt, readme.md, style.css and theme.json in that component\'s main folder, as a zip, after files that match common secrets are left out.'=>'Vain kun vahvistat siirron lisäosalle tai teemalle, joka ei ole WordPress.org-sivustolla: jokainen .php- ja .js-tiedosto, jokainen block.json-tiedosto sekä kyseisen osan pääkansion readme.txt, readme.md, style.css ja theme.json zip-pakettina sen jälkeen, kun yleisiä salaisuuksia vastaavat tiedostot on jätetty pois.','Open Babilim settings'=>'Avaa Babilim-asetukset','Original language'=>'Alkuperäinen kieli','Original string'=>'Alkuperäinen merkkijono','Paid'=>'Maksullinen','Partner'=>'Kumppani','Please check that your site can be reached from the internet, then try again.'=>'Tarkista, että sivustosi on tavoitettavissa internetistä, ja yritä sitten uudelleen.','Please choose a category for this report.'=>'Valitse tälle ilmoitukselle kategoria.','Plugin'=>'Lisäosa','Plugin · %s'=>'Lisäosa · %s','Plugins'=>'Lisäosat','Preview'=>'Esikatselu','Purchase restored. This site is now licensed.'=>'Ostos palautettu. Tällä sivustolla on nyt lisenssi.','Re-parsed entry count did not match the built index.'=>'Uudelleen jäsennettyjen merkintöjen määrä ei vastannut rakennettua indeksiä.','Re-verify'=>'Vahvista uudelleen','Rebuild index now'=>'Rakenna hakemisto uudelleen nyt','Refusing to write outside the Babilim language-file directory.'=>'Kirjoittaminen Babilimin kielitiedostohakemiston ulkopuolelle estetään.','Registration response was missing required fields.'=>'Rekisteröinnin vastauksesta puuttui pakollisia kenttiä.','Registration restarted.'=>'Rekisteröinti aloitettu uudelleen.','Remove'=>'Poista','Remove everything Babilim installed'=>'Poista kaikki Babilimin asentama','Remove everything Babilim installed? This deletes every language file it installed for every plugin and theme on this site.'=>'Poistetaanko kaikki Babilimin asentama? Tämä poistaa kaikki sen asentamat kielitiedostot kaikista tämän sivuston lisäosista ja teemoista (Teema).','Remove the %2$s translation of %1$s from this site?'=>'Poistetaanko komponentin %1$s käännös (%2$s) tältä sivustolta?','Removed %d installed component.'=>'Poistettu %d asennettu komponentti.' . "\0" . 'Poistettu %d asennettua komponenttia.','Removed after a failed integrity check'=>'Poistettu epäonnistuneen eheystarkistuksen jälkeen','Removed.'=>'Poistettu.','Removes every language file Babilim has installed for every plugin and theme on this site.'=>'Poistaa kaikki Babilimin asentamat kielitiedostot kaikista tämän sivuston lisäosista ja teemoista (Teema).','Report a problem'=>'Ilmoita ongelmasta','Report translation'=>'Ilmoita käännöksestä','Request newer translation'=>'Pyydä uudempaa käännöstä','Request translation'=>'Pyydä käännöstä','Requestable'=>'Pyydettävissä','Requesting…'=>'Pyydetään…','Restart registration'=>'Aloita rekisteröinti uudelleen','Restore code'=>'Palautuskoodi','Restore purchase'=>'Palauta osto','Retry request'=>'Yritä pyyntöä uudelleen','Roll back'=>'Palauta edellinen versio','Roll back and report'=>'Palauta edellinen versio ja ilmoita','Roll back and send report'=>'Palauta edellinen ja lähetä raportti','Roll back the %2$s translation of %1$s to the previous build?'=>'Palautetaanko kohteen %1$s käännös %2$s edelliseen koontiversioon?','Rolled back and reported.'=>'Palautettu ja ilmoitettu.','Rolled back to the previous build.'=>'Palautettu edelliseen versioon.','Rolled back, but the report could not be sent: %s'=>'Palautettu, mutta ilmoitusta ei voitu lähettää: %s','Rolling back would overwrite \'%1$s\' (%2$s), which is now served for another installed component (%3$s); nothing was changed.'=>'Aiempaan versioon palauttaminen ylikirjoittaisi tiedoston \'%1$s\' (%2$s), jota tarjotaan nyt toiselle asennetulle osalle (%3$s); mitään ei muutettu.','Rotate-token response was missing site_token.'=>'Tunnisteen vaihtovastauksesta puuttui site_token.','Save changes'=>'Tallenna muutokset','Scheduled, waiting to be processed'=>'Ajoitettu, odottaa käsittelyä','Search'=>'Hae','Search components'=>'Etsi komponentteja','Search the installed translations'=>'Hae asennetuista käännöksistä','Select all'=>'Valitse kaikki','Select fewer components: at most %1$d operations per run (you selected %2$d).'=>'Valitse vähemmän komponentteja: enintään %1$d toimintoa per ajo (valitsit %2$d).','Send report'=>'Lähetä raportti','Service plan'=>'Palvelupaketti','Settings'=>'Asetukset','Share error reports'=>'Jaa virheraportteja','Share this report'=>'Jaa tämä raportti','Show a new restore code'=>'Näytä uusi palautuskoodi','Show the "Report translation" entry in the admin toolbar'=>'Näytä ”Ilmoita käännös” -kohta hallinnan työkalupalkissa','Some of this component\'s text is hard-coded by its author and can\'t be translated by a language pack.'=>'Osa tämän komponentin tekstistä on tekijän kovakoodaamaa, eikä kielipaketti voi kääntää sitä.','Status'=>'Tila','Status unknown'=>'Tila tuntematon','String context'=>'Merkkijonon konteksti','Suggested translation'=>'Ehdotettu käännös','Supplementary translation index'=>'Täydentävä käännösindeksi','Supplementary translation index rebuilt.'=>'Täydentävä käännösindeksi on rakennettu uudelleen.','Supplementary translation maintenance'=>'Täydentävien käännösten ylläpito','Supplementary translations'=>'Täydentävät käännökset','Sweep aborted without orphaning anything: %s.'=>'Tarkistus keskeytettiin jättämättä mitään orvoksi: %s.','Sweep complete: %d file deleted.'=>'Tarkistus valmis: %d tiedosto poistettu.' . "\0" . 'Tarkistus valmis: %d tiedostoa poistettu.','Sweep now'=>'Tarkista nyt','Sync complete.'=>'Synkronointi valmis.','Thank you. Your report was sent.'=>'Kiitos. Ilmoituksesi lähetettiin.','That component is not installed on this site, so a translation cannot be requested for it.'=>'Tätä komponenttia ei ole asennettu tälle sivustolle, joten sille ei voi pyytää käännöstä.','That does not look like a restore code.'=>'Tämä ei näytä palautuskoodilta.','That is not a valid WordPress locale code. Nothing was saved.'=>'Tämä ei ole kelvollinen WordPress-kielikoodi. Mitään ei tallennettu.','That is not a valid build identifier.'=>'Tämä ei ole kelvollinen koontiversion tunniste.','The change could not be recorded in the translation index; please try again.'=>'Muutosta ei voitu tallentaa käännösindeksiin; yritä uudelleen.','The cleanup ran, but some of its changes could not be recorded in the translation index; the next cleanup will retry them.'=>'Siivous suoritettiin, mutta kaikkia sen muutoksia ei voitu tallentaa käännösindeksiin; seuraava siivous yrittää niitä uudelleen.','The component has no files that can be uploaded.'=>'Osassa ei ole tiedostoja, jotka voisi siirtää.','The component is not inside the plugins or themes directory.'=>'Osa ei ole lisäosien eikä teemojen hakemistossa.','The component\'s main file was not found.'=>'Osan päätiedostoa ei löytynyt.','The download response was missing a usable location.'=>'Latausvastauksesta puuttui käyttökelpoinen sijainti.','The entry opens a panel to search the translations Babilim installed on this site and report one of them.'=>'Kohta avaa paneelin, jossa voi hakea Babilimin tälle sivustolle asentamia käännöksiä ja ilmoittaa jonkin niistä.','The field "%1$s" is too long: it has %2$d characters and the limit is %3$d. Nothing was sent; please shorten it and try again.'=>'Kenttä "%1$s" on liian pitkä: siinä on %2$d merkkiä ja enimmäismäärä on %3$d. Mitään ei lähetetty; lyhennä kenttää ja yritä uudelleen.','The given domain \'%1$s\' matches neither the package manifest\'s own slug \'%2$s\' nor its text_domain \'%3$s\'.'=>'Annettu alue \'%1$s\' ei vastaa paketin manifestin omaa slugia \'%2$s\' eikä sen text_domain-arvoa \'%3$s\'.','The merged index for \'%s\' was rebuilt, but the translation index could not record it; the next rebuild will retry.'=>'Kielialueen %s yhdistetty indeksi rakennettiin uudelleen, mutta käännösindeksi ei voinut tallentaa sitä; seuraava uudelleenrakennus yrittää uudelleen.','The original text and the translations made from it will be provided to other sites that install the same version.'=>'Alkuperäinen teksti ja siitä tehdyt käännökset annetaan muille sivustoille, jotka asentavat saman version.','The package declares no main translation file.'=>'Paketti ei ilmoita pääkäännöstiedostoa.','The package has no %s for its own text domain.'=>'Paketissa ei ole tiedostoa %s sen omalle tekstialueelle.','The package manifest\'s kind \'%1$s\' does not match the requested kind \'%2$s\'.'=>'Paketin manifestin tyyppi \'%1$s\' ei vastaa pyydettyä tyyppiä \'%2$s\'.','The package produced no servable main translation file.'=>'Paketista ei syntynyt tarjottavaa pääkäännöstiedostoa.','The package\'s text domain \'%1$s\' does not match this site\'s copy of the component (\'%2$s\'), so it was not installed.'=>'Paketin tekstialue \'%1$s\' ei vastaa tämän sivuston kopion tekstialuetta (\'%2$s\'), joten sitä ei asennettu.','The packaged component could not be read.'=>'Paketoitua osaa ei voitu lukea.','The registration challenge is not in the expected form.'=>'Rekisteröintihaaste ei ole odotetussa muodossa.','The report could not be sent.'=>'Raporttia ei voitu lähettää.','The search could not be completed.'=>'Hakua ei voitu suorittaa loppuun.','The service asked this site to wait before syncing again.'=>'Palvelu pyysi tätä sivustoa odottamaan ennen seuraavaa synkronointia.','The service could not reach your site. A firewall, security plugin or host rule is probably blocking the request; please allow requests to /wp-json/babilim/v1/challenge.'=>'Palvelu ei tavoittanut sivustoasi. Palomuuri, tietoturvalisäosa tai palveluntarjoajan sääntö estää luultavasti pyynnön; salli pyynnöt osoitteeseen /wp-json/babilim/v1/challenge.','The service\'s upload offer was incomplete.'=>'Palvelun lähetystarjous oli puutteellinen.','The text domain \'%1$s\' (%2$s) is already served for another installed component (%3$s); nothing was installed.'=>'Tekstialue \'%1$s\' (%2$s) on jo käytössä toiselle asennetulle osalle (%3$s); mitään ei asennettu.','The upload is kept until you ask Babilim to delete it.'=>'Siirrettyä aineistoa säilytetään, kunnes pyydät Babilimia poistamaan sen.','Theme'=>'Teema','Theme · %s'=>'Teema · %s','Themes'=>'Teemat','There is no upload in progress.'=>'Käynnissä olevaa siirtoa ei ole.','There is no upload waiting for confirmation.'=>'Vahvistusta odottavaa siirtoa ei ole.','These are the languages this site uses. You can change them in %s.'=>'Nämä ovat kielet, joita tämä sivusto käyttää. Voit muuttaa niitä kohdassa %s.','These fields will be sent:'=>'Nämä kentät lähetetään:','This build is not one this site currently knows about for this component/locale.'=>'Tämä sivusto ei tällä hetkellä tunne tätä versiota tälle komponentille ja kielelle.','This component does not declare a version number, so a translation cannot be requested for it.'=>'Tämä komponentti ei ilmoita versionumeroa, joten sille ei voi pyytää käännöstä.','This component is larger than the service accepts, so it cannot be uploaded.'=>'Tämä osa on suurempi kuin palvelu hyväksyy, joten sitä ei voi lähettää.','This component was already uploaded. Babilim is checking it now.'=>'Tämä komponentti on jo lähetetty. Babilim tarkistaa sitä parhaillaan.','This component\'s version number is longer than %d characters, which Babilim cannot handle, so a translation cannot be requested for it.'=>'Tämän komponentin versionumero on pidempi kuin %d merkkiä, mitä Babilim ei pysty käsittelemään, joten sille ei voi pyytää käännöstä.','This issues a new restore code and the previous one stops working. Continue?'=>'Tämä luo uuden palautuskoodin, ja edellinen lakkaa toimimasta. Jatketaanko?','This network has too many sites to check them one by one, and some of them may be set to erase their Babilim identity when the plugin is deleted. The paid license attached to such a site could then not be restored automatically; you would have to contact Babilim support at %s. To keep the identities, press Cancel, untick "Delete all Babilim data on uninstall" in each site\'s Babilim settings, and deactivate again. Deactivate anyway?'=>'Tässä verkostossa on liian monta sivustoa tarkistettavaksi yksitellen, ja jotkin niistä saattavat olla asetettu tyhjentämään Babilim-tunnisteensa, kun lisäosa poistetaan. Tällaiseen sivustoon liitettyä maksullista lisenssiä ei sen jälkeen voisi palauttaa automaattisesti, vaan sinun pitäisi ottaa yhteyttä Babilim-tukeen osoitteessa %s. Säilyttääksesi tunnisteet paina Peruuta, poista valinta kohdasta "Poista kaikki Babilim-tiedot poistettaessa" kunkin sivuston Babilim-asetuksista ja poista käytöstä uudelleen. Poistetaanko käytöstä silti?','This plugin\'s own version, so the service can tell you to update it if it\'s too old to talk to.'=>'Tämän lisäosan oma versio, jotta palvelu voi kehottaa päivittämään sen, jos se on liian vanha yhteydenpitoon.','This report does not name a valid plugin or theme and locale.'=>'Tämä ilmoitus ei nimeä kelvollista lisäosaa tai teemaa ja kielialuetta.','This report does not name an installed string.'=>'Tämä raportti ei nimeä asennettua merkkijonoa.','This report is missing a valid build to report against.'=>'Tästä raportista puuttuu kelvollinen versio, jota vastaan raportoida.','This report will be posted publicly on GitHub and may be kept by third parties.'=>'Tämä raportti julkaistaan julkisesti GitHubissa, ja kolmannet osapuolet saattavat säilyttää sen.','This restore code was not recognised for this site.'=>'Tätä palautuskoodia ei tunnistettu tälle sivustolle.','This site already has an active registration that can no longer be recovered automatically.'=>'Tällä sivustolla on jo aktiivinen rekisteröinti, jota ei voi enää palauttaa automaattisesti.','This site has %1$d components across %2$d languages, which needs %3$d check batches; Babilim can handle at most %4$d per run. Reduce the managed languages in Settings or deactivate unused plugins and themes, then press Check again now.'=>'Tällä sivustolla on %1$d osaa %2$d kielellä, mikä vaatii %3$d tarkistuserää. Babilim voi käsitellä enintään %4$d erää ajokertaa kohden. Vähennä hallittavia kieliä kohdassa Asetukset tai poista käytöstä käyttämättömät lisäosat ja teemat, ja paina sitten Tarkista uudelleen nyt.','This site has no purchase to show a code for.'=>'Tällä sivustolla ei ole ostosta, jonka koodi voitaisiin näyttää.','This site is already licensed. Reload the page.'=>'Tällä sivustolla on jo lisenssi. Lataa sivu uudelleen.','This site is not registered with Babilim yet.'=>'Tätä sivustoa ei ole vielä rekisteröity Babilimiin.','This site is over the size the service accepts in one sync, so some items were left out: %1$d components and %2$d locales.'=>'Tämä sivusto ylittää koon, jonka palvelu hyväksyy yhdessä synkronoinnissa, joten osa kohteista jätettiin pois: %1$d komponenttia ja %2$d kieltä.','This site is part of a multisite network, which does not install new translations automatically. Translations that are already installed are still updated.'=>'Tämä sivusto kuuluu multisite-verkkoon, joka ei asenna uusia käännöksiä automaattisesti. Jo asennetut käännökset kuitenkin päivitetään edelleen.','This site is verified.'=>'Tämä sivusto on vahvistettu.','This site must be verified first.'=>'Tämä sivusto on vahvistettava ensin.','This site\'s URL, so the service can verify you own it.'=>'Sivuston verkko-osoite, jotta palvelu voi varmistaa sinun omistavan sen.','This site\'s address is too long for Babilim to register.'=>'Tämän sivuston osoite on liian pitkä, jotta Babilim voisi rekisteröidä sen.','This site\'s configured locale.'=>'Sivuston määritetty kielialue.','This site\'s install public key, used to prove requests genuinely come from this site. Only the public half is ever sent.'=>'Tämän asennuksen julkinen avain, jolla todistetaan pyyntöjen tulevan aidosti tältä sivustolta. Vain julkinen puoli lähetetään.','This site\'s locale code is not one Babilim can register.'=>'Tämän sivuston kielikoodia ei voi rekisteröidä Babilimissa.','This string can\'t be reported from this site.'=>'Tätä merkkijonoa ei voi ilmoittaa tältä sivustolta.','This string is not among the translations installed on this site. Search again and pick it from the list.'=>'Tämä merkkijono ei kuulu tälle sivustolle asennettuihin käännöksiin. Hae uudelleen ja valitse se luettelosta.','This translation was updated since you searched. Search again and pick the string from the new list.'=>'Tätä käännöstä on päivitetty hakusi jälkeen. Hae uudelleen ja valitse merkkijono uudesta luettelosta.','To translate this component, Babilim needs its source.'=>'Komponentin kääntämiseksi Babilim tarvitsee sen lähdekoodin.','Too many attempts. Try again tomorrow.'=>'Liian monta yritystä. Yritä huomenna uudelleen.','Too many reports today. Try again tomorrow.'=>'Liian monta raporttia tänään. Yritä huomenna uudelleen.','Too many requests.'=>'Liian monta pyyntöä.','Toolbar'=>'Työkalupalkki','Translating…'=>'Käännetään…','Translation does not load'=>'Käännös ei lataudu','Translation failed'=>'Käännös epäonnistui','Translation files you put in %s always take priority over Babilim\'s. They are kept unless you uncheck this.'=>'Käännöstiedostot, jotka sijoitat kohteeseen %s, ovat aina etusijalla Babilimin tiedostoihin nähden. Ne säilytetään, ellet poista tämän valintaa.','Translation requested.'=>'Käännöstä pyydetty.','Translations'=>'Käännökset','Type'=>'Tyyppi','Type at least 2 characters to search.'=>'Kirjoita vähintään 2 merkkiä hakeaksesi.','Unexpected HTTP %d response.'=>'Odottamaton HTTP-vastaus %d.','Uninstall'=>'Asennuksen poisto','Unknown kind: %s'=>'Tuntematon tyyppi: %s','Unsafe domain: %s'=>'Vaarallinen tekstialue: %s','Unsafe locale: %s'=>'Vaarallinen kielialue: %s','Unsafe slug: %s'=>'Vaarallinen tunniste (slug): %s','Unsafe text_domain: %s'=>'Vaarallinen text_domain: %s','Up to 20 pending diagnostic events (e.g. a file that failed its integrity check), each just a code, component, and locale, and never any string content or translated text.'=>'Enintään 20 odottavaa diagnostiikkatapahtumaa (esim. tiedosto, joka ei läpäissyt eheystarkistusta), joissa kussakin on vain koodi, komponentti ja kielialue, eikä koskaan merkkijonojen sisältöä tai käännettyä tekstiä.','Update'=>'Päivitä','Update available'=>'Päivitys saatavilla','Updates'=>'Päivitykset','Updating…'=>'Päivitetään…','Upgrade this site'=>'Päivitä tämä sivusto','Upload and request'=>'Siirrä ja pyydä','Upload cancelled.'=>'Siirto peruttu.','Upload complete — translation requested.'=>'Siirto valmis – käännöstä pyydetty.','Upload expired before it finished'=>'Siirto vanheni ennen valmistumista','Upload in progress — continue or cancel'=>'Siirto käynnissä – jatka tai peruuta','Upload this component?'=>'Siirrä tämä komponentti?','Upload was not accepted'=>'Siirtoa ei hyväksytty','Uploading'=>'Siirretään','Uploading part %1$d of %2$d…'=>'Siirretään osaa %1$d / %2$d…','Uploading…'=>'Siirretään…','Verified'=>'Vahvistettu','Verify response was missing site_token.'=>'Vahvistusvastauksesta puuttui site_token.','Version %s'=>'Versio %s','What is sent when Babilim checks this site'=>'Mitä lähetetään, kun Babilim tarkistaa tämän sivuston','What is sent when you enable Babilim'=>'Mitä lähetetään, kun otat Babilimin käyttöön','When something fails inside Babilim, send an error report to the Babilim service so it can be published as a public issue on GitHub. The report is sent as coming from this site, with the same authentication as every other request to the Babilim service. The service publishes only the error code and versions as a public issue on GitHub; the public issue contains no site address, content or file paths. Off by default.'=>'Kun Babilimin sisällä jokin epäonnistuu, lähetä virheraportti Babilim-palvelulle, jotta se voidaan julkaista julkisena ongelmana GitHubissa. Raportti lähetetään tämän sivuston puolesta samalla todennuksella kuin kaikki muutkin Babilim-palvelulle tehtävät pyynnöt. Palvelu julkaisee julkisena ongelmana GitHubissa vain virhekoodin ja versiot; julkinen ongelma ei sisällä sivuston osoitetta, sisältöä eikä tiedostopolkuja. Pois käytöstä oletuksena.','Where you saw this (optional)'=>'Missä näit tämän (valinnainen)','While this is on, translations the service lists as available for the languages you manage are installed during the twice-daily sync.'=>'Kun tämä on käytössä, käännökset, jotka palvelu ilmoittaa saatavilla oleviksi hallinnoimillesi kielille, asennetaan kahdesti päivässä tapahtuvan synkronoinnin aikana.','WordPress.org'=>'WordPress.org','Wrong for this context'=>'Väärä tässä kontekstissa','Wrong meaning'=>'Väärä merkitys','Wrong plural form'=>'Väärä monikkomuoto','Wrong term'=>'Väärä termi','Yes'=>'Kyllä','You are not allowed to do this.'=>'Sinulla ei ole oikeutta tähän toimintoon.','Your PHP version, for compatibility.'=>'PHP-versiosi yhteensopivuuden varmistamiseksi.','Your WordPress version, to serve compatible translation files.'=>'WordPress-versiosi, jotta yhteensopivat käännöstiedostot voidaan toimittaa.','Your new restore code: %s. Keep it somewhere safe — the previous code no longer works.'=>'Uusi palautuskoodisi: %s. Säilytä se turvallisessa paikassa — edellinen koodi ei enää toimi.','Your report is processed automatically by AI models and may improve this translation for other sites.'=>'Raporttisi käsitellään automaattisesti AI-malleilla, ja se voi parantaa tätä käännöstä muilla sivustoilla.','Your site answered, but not with what was expected. The REST API may be rewritten by another plugin, or that endpoint may be cached; please exclude /wp-json/babilim/v1/challenge from caching and rewriting.'=>'Sivustosi vastasi, mutta ei odotetulla tavalla. Jokin toinen lisäosa saattaa muokata REST API:a tai kyseinen päätepiste voi olla välimuistissa; sulje /wp-json/babilim/v1/challenge välimuistin ja uudelleenkirjoituksen ulkopuolelle.','Your site took too long to answer. Please try again later, and check that your host is not too slow or overloaded.'=>'Sivustosi vastasi liian hitaasti. Yritä myöhemmin uudelleen ja tarkista, ettei palveluntarjoajasi palvelin ole liian hidas tai ylikuormitettu.','Zip has no manifest.json.'=>'Zip-tiedostossa ei ole manifest.json-tiedostoa.','Zip is missing expected default file: %s'=>'Zip-paketista puuttuu odotettu default-tiedosto: %s','Zip is missing expected file: %s'=>'Zip-paketista puuttuu odotettu tiedosto: %s','_manifest.json has an unexpected structure'=>'Tiedostolla _manifest.json on odottamaton rakenne','could not read _manifest.json: %s'=>'tiedostoa _manifest.json ei voitu lukea: %s','expected_manifest is missing or has an invalid \'%s\'.'=>'Kenttä \'%s\' puuttuu kohteesta expected_manifest tai se on virheellinen.','expected_manifest\'s \'server_build_id\' is not a valid build id.'=>'Kohteen expected_manifest kenttä \'server_build_id\' ei ole kelvollinen koontitunniste.','failed to parse _manifest.json: %s'=>'_manifest.json-tiedoston jäsentäminen epäonnistui: %s','it would orphan %1$d of %2$d managed components (more than half)'=>'se jättäisi orvoksi %1$d / %2$d hallitusta komponentista (yli puolet)','it would orphan every managed %1$s component (%2$d of %2$d)'=>'se jättäisi orvoksi kaikki hallitut komponentit tyyppiä %1$s (%2$d/%2$d)','l10n.php entry count mismatch for %s'=>'l10n.php-merkintöjen määrä ei täsmää: %s','manifest.json has an invalid \'default_domain_entries\'.'=>'Tiedoston manifest.json kenttä \'default_domain_entries\' on virheellinen.','manifest.json has an invalid \'default_domain_files\'.'=>'Tiedoston manifest.json kenttä \'default_domain_files\' on virheellinen.','manifest.json in the zip is not valid JSON.'=>'Zip-tiedoston manifest.json ei ole kelvollista JSON-muotoa.','manifest.json is missing or has an invalid \'%s\'.'=>'Tiedostosta manifest.json puuttuu kenttä \'%s\' tai se on virheellinen.','manifest.json is missing or has an invalid \'build_no\'.'=>'Tiedostosta manifest.json puuttuu kenttä \'build_no\' tai se on virheellinen.','manifest.json is missing or has an invalid \'entries\'.'=>'Tiedostosta manifest.json puuttuu kenttä \'entries\' tai se on virheellinen.','manifest.json is missing or has an invalid \'extra_domains\'.'=>'Tiedostosta manifest.json puuttuu kenttä \'extra_domains\' tai se on virheellinen.','manifest.json is missing or has an invalid \'files\'.'=>'Tiedostosta manifest.json puuttuu kenttä \'files\' tai se on virheellinen.','manifest.json\'s \'%s\' does not match the expected value.'=>'Tiedoston manifest.json kenttä \'%s\' ei vastaa odotettua arvoa.','manifest.json\'s \'contract\' is not a valid version string.'=>'Tiedoston manifest.json kenttä \'contract\' ei ole kelvollinen versiomerkkijono.','manifest.json\'s \'kind\' must be \'plugin\' or \'theme\'.'=>'Tiedoston manifest.json kentän \'kind\' arvon on oltava \'plugin\' tai \'theme\'.','manifest.json\'s \'server_build_id\' is not a valid build id.'=>'Tiedoston manifest.json kenttä \'server_build_id\' ei ole kelvollinen koontitunniste.','manifest.json\'s \'status\' must be \'published\'.'=>'Tiedoston manifest.json kentän \'status\' on oltava \'published\'.','nonce must be a hexadecimal string.'=>'nonce-arvon on oltava heksadesimaalimerkkijono.','per day'=>'päivässä','rc_…'=>'rc_…','sha256 mismatch for %s'=>'sha256-arvo ei täsmää: %s','sha256 mismatch for default/%s'=>'sha256-arvo ei täsmää: default/%s','component kind in the sweep brake messageplugin'=>'lisäosa','component kind in the sweep brake messagetheme'=>'teema','problem report categoryOther'=>'Muu','translation statusAvailable'=>'Saatavilla','translation statusInstalled'=>'Asennettu']];